    @GameTest(template="empty") public static void missingHandTargetClearsWholeTagAndRetainsUnpaidInputWithoutRecursion(GameTestHelper h){try(Fixture f=new Fixture(h)){var a=f.mirror(0);HandMirrorMenu menu=f.menu(a,InteractionHand.MAIN_HAND);f.player.getMainHandItem().getOrCreateTag().putString("custom","old");h.getLevel().setBlock(a.getBlockPos(),Blocks.AIR.defaultBlockState(),3);menu.input.setItem(0,new ItemStack(Items.COBBLESTONE,7));h.assertTrue(!f.player.getMainHandItem().hasTag()&&menu.input.getItem(0).getCount()==7&&!menu.stillValid(f.player),"Missing target erased input or retained original whole tag");menu.removed(f.player);h.assertTrue(f.player.getInventory().items.stream().filter(s->s.is(Items.COBBLESTONE)).mapToInt(ItemStack::getCount).sum()==7,"Failed hand input was lost on close");}h.succeed();}
    @GameTest(template="empty") public static void unavailableHandTargetLeavesLinkAndRetainsInputForPersistentCloseRefund(GameTestHelper h){try(Fixture f=new Fixture(h)){var a=f.mirror(0);HandMirrorMenu menu=f.menu(a,InteractionHand.MAIN_HAND);var key=ResourceKey.create(Registries.DIMENSION,ResourceLocation.fromNamespaceAndPath("test","missing"));new MirrorLink(key,f.centre).writeTo(f.player.getMainHandItem());menu.input.setItem(0,new ItemStack(Items.COBBLESTONE,3));h.assertTrue(f.player.getMainHandItem().hasTag()&&a.queuedCount()==0&&menu.input.getItem(0).getCount()==3,"Unavailable endpoint erased link/input");for(int i=0;i<36;i++)if(i!=0)f.player.getInventory().setItem(i,new ItemStack(Items.DIRT,64));menu.removed(f.player);h.assertTrue(MirrorRefundSavedData.get(h.getLevel()).pendingCount(f.player.blockPosition())==3,"Full-inventory hand close had no durable unpaid owner");MirrorRefundSavedData.get(h.getLevel()).tick(h.getLevel());h.assertTrue(f.count(Items.COBBLESTONE)==3,"Persistent close refund did not emit paid input");}h.succeed();}
    @GameTest(template="empty") public static void handMirrorItemsCannotBeInsertedOrShiftMoved(GameTestHelper h){try(Fixture f=new Fixture(h)){var a=f.mirror(0);HandMirrorMenu menu=f.menu(a,InteractionHand.MAIN_HAND);ItemStack other=CatalogModule.stack("hand_mirror");h.assertTrue(!menu.slots.get(0).mayPlace(other),"Hand mirror accepted itself as transport input");f.player.getInventory().setItem(9,other);h.assertTrue(menu.quickMoveStack(f.player,1).isEmpty()&&f.player.getInventory().getItem(9)==other&&a.queuedCount()==0,"Shift click transported another hand mirror");}h.succeed();}
    @GameTest(template="empty") public static void originalInstabilityThresholdIsStrictAndDecayStartsAtCountZero(GameTestHelper h){try(Fixture f=new Fixture(h)){var a=f.mirror(0);ChunkPos cp=new ChunkPos(f.centre);AuraChunk aura=AuraSavedData.get(h.getLevel()).getOrCreate(cp,100);float oldVis=aura.getVis(),oldFlux=aura.getFlux();try{AuraManager.drainFlux(h.getLevel(),f.centre,32766,false);a.addInstability(128);a.serverTick();h.assertTrue(a.instability()==127&&aura.getFlux()==0,"Strict128 threshold/count0 decay changed");a.addInstability(2);a.serverTick();h.assertTrue(a.instability()==1&&aura.getFlux()==1,"129 did not pollute exactly1/subtract128once");a.addInstability(400);a.serverTick();h.assertTrue(a.instability()==273&&aura.getFlux()==2,"Large excess was purged in a loop");}finally{AuraManager.drainVis(h.getLevel(),f.centre,32766,false);AuraManager.addVis(h.getLevel(),f.centre,oldVis);AuraManager.drainFlux(h.getLevel(),f.centre,32766,false);AuraManager.addFlux(h.getLevel(),f.centre,oldFlux);}}h.succeed();}
    @GameTest(template="empty") public static void staleOldEndpointCannotInvalidateDifferentLaterPair(GameTestHelper h){try(Fixture f=new Fixture(h)){var a=f.mirror(-3);var b=f.mirror(0);var c=f.mirror(3);f.pair(b,c);a.setLink(b.endpoint());a.invalidateLink();h.assertTrue(b.isLinkValid()&&c.isLinkValid()&&b.link().equals(c.endpoint()),"Stale endpoint invalidated another paid later pair");}h.succeed();}
    @GameTest(template="empty") public static void randomEntrySelectionIsNotFIFOAndQueuesRemainUnmerged(GameTestHelper h){try(Fixture f=new Fixture(h)){var a=f.mirror(0);a.transportDirect(new ItemStack(Items.COAL,3));a.transportDirect(new ItemStack(Items.IRON_INGOT,3));f.ticks(a,21);h.getLevel().random.setSeed(0);a.serverTick();h.assertTrue(f.count(Items.COAL)==0&&f.count(Items.IRON_INGOT)==1&&a.queuedCount()==5&&a.queuedStacks().size()==2,"Native uniform entry selection became FIFO/whole-stack delivery");}h.succeed();}
    @GameTest(template="empty") public static void reentrantQueueReceiveCannotReplayInFlightEjection(GameTestHelper h){try(Fixture f=new Fixture(h)){var a=f.mirror(0);a.transportDirect(new ItemStack(Items.COBBLESTONE,4));f.ticks(a,21);Consumer<EntityJoinLevelEvent> listener=event->{if(event.getEntity() instanceof ItemEntity item&&item.blockPosition().equals(a.getBlockPos())&&item.getItem().is(Items.COBBLESTONE)){a.transportDirect(new ItemStack(Items.COBBLESTONE,2));a.serverTick();}};MinecraftForge.EVENT_BUS.addListener(listener);try{a.serverTick();}finally{MinecraftForge.EVENT_BUS.unregister(listener);}h.assertTrue(f.count(Items.COBBLESTONE)==1&&a.queuedCount()==5&&a.queuedStacks().size()==2,"Reentrant receive replayed reserved unit or erased new queue entry");}h.succeed();}
    @GameTest(template="empty") public static void refundReservationRejectsReentryAndRetiresAcceptedEntryByIdentity(GameTestHelper h){try(Fixture f=new Fixture(h)){var data=new MirrorRefundSavedData();data.add(f.centre,Direction.UP,new ItemStack(Items.COBBLESTONE));boolean[] once={false};Consumer<EntityJoinLevelEvent> listener=event->{if(!once[0]&&event.getEntity() instanceof ItemEntity item&&item.blockPosition().equals(f.centre)&&item.getItem().is(Items.COBBLESTONE)){once[0]=true;data.add(f.centre,Direction.UP,new ItemStack(Items.COBBLESTONE,4));data.tick(h.getLevel());}};MinecraftForge.EVENT_BUS.addListener(listener);try{data.tick(h.getLevel());}finally{MinecraftForge.EVENT_BUS.unregister(listener);}h.assertTrue(data.pendingCount()==4&&f.count(Items.COBBLESTONE)==1,"Refund callback replayed accepted reservation or erased appended owner");data.tick(h.getLevel());data.tick(h.getLevel());h.assertTrue(data.pendingCount()==0&&f.count(Items.COBBLESTONE)==5,"Refund entry was emitted twice after later retry");}h.succeed();}
    @GameTest(template="empty") public static void persistentRefundDoesNotForceUnavailableChunk(GameTestHelper h){try(Fixture f=new Fixture(h)){var data=new MirrorRefundSavedData();BlockPos far=new BlockPos(28000000,264,28000000);data.add(far,Direction.NORTH,new ItemStack(Items.COBBLESTONE,6));data.tick(h.getLevel());h.assertTrue(data.pendingCount()==6&&h.getLevel().getChunkSource().getChunkNow(far.getX()>>4,far.getZ()>>4)==null,"Refund created a chunk ticket or erased unavailable paid item");var restored=MirrorRefundSavedData.load(data.save(new CompoundTag()));h.assertTrue(restored.pendingCount()==6,"Unavailable owner did not persist");}h.succeed();}
    @GameTest(template="empty") public static void canceledFullInventoryHandCloseAndLogoutRefundRemainOwnedExactlyOnce(GameTestHelper h){try(Fixture f=new Fixture(h)){var a=f.mirror(0);HandMirrorMenu menu=f.menu(a,InteractionHand.MAIN_HAND);f.player.getInventory().selected=1;for(int i=1;i<36;i++)f.player.getInventory().setItem(i,new ItemStack(Items.DIRT,64));menu.input.setItem(0,new ItemStack(Items.COBBLESTONE,5));BlockPos refund=f.player.blockPosition();Consumer<EntityJoinLevelEvent> veto=vetoAt(refund);MinecraftForge.EVENT_BUS.addListener(veto);try{menu.removed(f.player);menu.removed(f.player);MinecraftForge.EVENT_BUS.post(new net.minecraftforge.event.entity.player.PlayerEvent.PlayerLoggedOutEvent(f.player));MirrorRefundSavedData.get(h.getLevel()).tick(h.getLevel());h.assertTrue(MirrorRefundSavedData.get(h.getLevel()).pendingCount(refund)==5&&f.count(Items.COBBLESTONE)==0,"Close/logout canceled refund lost or repeated input");}finally{MinecraftForge.EVENT_BUS.unregister(veto);}MirrorRefundSavedData.get(h.getLevel()).tick(h.getLevel());h.assertTrue(f.count(Items.COBBLESTONE)==5&&MirrorRefundSavedData.get(h.getLevel()).pendingCount(refund)==0,"Canceled hand close refund did not retry once");}h.succeed();}
    @GameTest(template="empty",timeoutTicks=100) public static void actualWorldTicksDriveMountedQueueAndAcceptedPhysicalOutput(GameTestHelper h){
        Fixture f=new Fixture(h);var a=f.mirror(0);a.transportDirect(new ItemStack(Items.COBBLESTONE,40));long before=h.getLevel().getGameTime();
        h.runAfterDelay(32,()->{try{long elapsed=h.getLevel().getGameTime()-before;h.assertTrue(elapsed>=30&&a.count()>=30,"Native block entity did not advance with real world ticks");h.assertTrue(a.queuedCount()<40&&a.queuedCount()+f.count(Items.COBBLESTONE)==40,"Actual physical world output did not conserve queued40");h.assertTrue(a.queuedCount()==61-a.count(),"Original count>20 one-item cadence changed under native world ticks");}finally{f.close();}h.succeed();});
    }
    @GameTest(template="empty",timeoutTicks=180) public static void loadedCrossDimensionPairMovesPhysicalItemAndEmitsOnlyInRemoteWorld(GameTestHelper h){
        Fixture f=new Fixture(h);var a=f.mirror(0);ServerLevel remote=h.getLevel().getServer().getLevel(Level.NETHER);h.assertTrue(remote!=null,"Native Nether world unavailable");BlockPos pos=new BlockPos(f.centre.getX(),100,f.centre.getZ());remote.getChunkAt(pos);
        h.startSequence().thenWaitUntil(()->h.assertTrue(remote.getChunkSource().getChunkNow(pos.getX()>>4,pos.getZ()>>4)!=null,"Native remote fixture chunk is not ready"))
            .thenExecute(()->{BlockState old=remote.getBlockState(pos),support=remote.getBlockState(pos.below());var previousTile=remote.getBlockEntity(pos);CompoundTag previousTag=previousTile==null?null:previousTile.saveWithoutMetadata();List<ItemEntity> emitted=new ArrayList<>();ItemMirrorBlockEntity[] receiver={null};
                Consumer<EntityJoinLevelEvent> joins=event->{if(event.getLevel()==remote&&event.getEntity() instanceof ItemEntity item&&item.blockPosition().equals(pos)&&item.getItem().is(Items.COBBLESTONE))emitted.add(item);};
                MinecraftForge.EVENT_BUS.addListener(net.minecraftforge.eventbus.api.EventPriority.LOWEST,true,joins);try{
                remote.setBlock(pos.below(),Blocks.STONE.defaultBlockState(),3);remote.setBlock(pos,CatalogBlocks.block("mirror").defaultBlockState().setValue(MirrorBlock.FACING,Direction.UP),3);var b=(ItemMirrorBlockEntity)remote.getBlockEntity(pos);
                receiver[0]=b;
                b.setLink(a.endpoint());h.assertTrue(b.restoreLink()&&a.isLinkValid()&&a.link().dimension()==Level.NETHER,"Namespaced cross-dimension reciprocal restoration failed");ItemEntity source=f.entity(new ItemStack(Items.COBBLESTONE,3),a.getBlockPos());h.assertTrue(a.transport(source)&&b.queuedCount()==3&&a.instability()==3,"Cross-dimension physical collision failed payment");for(int i=0;i<22;i++)b.serverTick();
                // A loaded FULL Nether chunk need not be tracked by players; its real entities are
                // accepted and persisted but absent from visibility-filtered getEntitiesOfClass.
                List<ItemEntity> accepted=emitted.stream().filter(e->e.isAddedToWorld()&&!e.isRemoved()&&e.isAlive()).toList();
                h.assertTrue(b.queuedCount()==2,"Remote queue did not retain2 paid units; actual="+b.queuedCount());
                h.assertTrue(accepted.size()==1,"Remote native join did not own exactly1 physical output; accepted="+accepted.size()+", observed="+emitted.size());ItemEntity out=accepted.get(0);
                h.assertTrue(out.level()==remote&&out.getItem().is(Items.COBBLESTONE)&&out.getItem().getCount()==1&&out.getPortalCooldown()==20&&out.blockPosition().equals(pos),"Accepted output was not native1-item receiver-world entity");
                h.assertTrue(b.queuedCount()+out.getItem().getCount()==3&&f.count(Items.COBBLESTONE)==0,"Cross-dimension physical payment conservation failed");
            }finally{
                if(receiver[0]!=null&&remote.getBlockEntity(pos)==receiver[0]){receiver[0].load(receiver[0].getUpdateTag());receiver[0].setCreativeRemoval(true);}
                remote.setBlock(pos,old,3);if(previousTag!=null&&remote.getBlockEntity(pos)!=null)remote.getBlockEntity(pos).load(previousTag);remote.setBlock(pos.below(),support,3);
                // Only test-captured physical outputs are removed, including untracked accepted entities.
                emitted.forEach(Entity::discard);MinecraftForge.EVENT_BUS.unregister(joins);f.close();}}).thenSucceed();
    }
